function configurar(reintentos, silencioso) {
  reintentos = reintentos || 3;
  silencioso = silencioso || true;
  return { reintentos, silencioso };
}

function crearOpciones(limite = 5, etiqueta = 'general') {
  return { limite, etiqueta };
}

function opciones(silencioso) {
  silencioso = silencioso || true;
  return { silencioso };
}
